  str_pet_skin_name_1501903 = "나른한 풍요",
  str_pet_skin_name_1602273 = "바다에 바치는 매의 시",
  str_pet_skin_name_1601733 = "핏빛 관용",
  str_pet_skin_name_1602183 = "야심 가득한 제안",
  str_pet_skin_name_1500973 = "강철의 한 획",
  str_pet_skin_name_1400953 = "비질란테의 구원",
  str_pet_skin_desc_1500333 = "바이스가 해신제에 참가하기 위해 선택한 심플하고 편안한 스타일의 수영복이다. 이 의상은 바이스의 착용 습관에 적합하도록 특수한 디자인 구조를 접목했고, 꼬리에도 불편함을 주지 않는다. 또한 블랙과 골드 컬러의 자외선 차단용 외투는 활발하고 활동적인 그녀의 성향에 잘 어울리는 것을 느낄 수 있다. 비치발리볼, 상쾌한 음료, 빙수 카트... 시원한 얼음을 만들고 있는 제빙기 소리, 활짝 웃으며 물놀이를 권하는 단발머리의 소녀... 그 여름, 바이스는 당신과 특별한 추억을 함께 나누었다.",
  str_pet_skin_desc_1600063 = "해신제를 테마로 디자인된 순백의 소녀 스타일 의상이다. 백야성의 고귀하고 우아한 숙녀를 위한 디자인으로, 바닷바람에 흔들리는 시폰은 소녀를 위해 뜨거운 햇살을 막아준다. 또한 펜던트를 어떻게 코디하면 좋을지 계속 고민했던 카렌은 마침내 정답을 찾아 스타일을 완성시킬 수 있었다. 이 옷차림을 한 카렌은 잠시나마 귀족으로서 품고 있는 고뇌를 내려놓고, 상쾌한 여름을 즐기는 순수한 마음의 소녀로 돌아갈 수 있었다.",
  str_pet_skin_desc_1601033 = "첫눈에 엘시를 매료시킨 소악마 스타일의 수영복이다. 금속 체인, 하트 안대, 블랙 앤 골드 머리띠... 전반적인 스타일과 디테일 모두 정교함과 호화로움을 드러내며, 그러면서도 짙은 색상의 레이스 프릴과 크로스 밴드 디자인은 귀여운 분위기를 자아낸다. 공허의 눈동자 또한 엘시의 모습에 맞춰 변화했고, 이유는 알 수 없지만 엘시가 이 옷을 입고 있을 때는 어디선가 고양이 울음소리가 들려오기도 한다.",
  str_pet_skin_desc_1500763 = "클레이튼은 남자라도 자외선 차단제가 필요하다고 강조하며, 심해에서의 모험에 매우 적합한 용사의 수영복을 선택했다. 이 수영복은 움브라톤에서 가장 유행하는 배색을 차용했고, 디자인은 클레이튼의 평소 취향을 강하게 반영하고 있는 듯하다. 깊게 파인 칼라는 열기를 식혀주며, 더 많은 촉수를 품는 것도 가능해 보인다. 또한 자외선을 차단하는 외투는 태양을 좋아하지 않는 그가 무자비한 햇볕이 내리쬐는 해변에서도 자유롭게 다닐 수 있도록 돕는다. 물속에서 더욱 자유롭게 움직이고 있는 클레이튼은 당신에게 함께 이 순간을 음미하자는 신호를 보내는 것처럼 보인다.",
  str_pet_skin_desc_1400863 = "해신제를 테마로 디자인된 순백의 소녀 스타일 의상이다. 우라이아의 신분을 고려해 특별히 티 없이 새하얀 순백의 염료를 사용했고, 이를 통해 순수함과 경건함을 표현했다. 꽃 덩굴이 그녀의 곁을 지키며 부름을 기다리는 모습, 그리고 그녀의 태도와 기품은 사람들의 눈에는 평소와 다를 바가 없어 보인다. 그러나 해변에 온 우라이아가 처음 입어보는 이 옷에 내심 수줍어하고 있다는 것은 그녀의 주변을 감싸는 꽃들만이 알고 있다. 맑은 하늘, 바다 내음이 담긴 바람, 시원한 파도... 그녀가 손에 든 의례의 검을 휘두를 때면, 아름다운 시와 음악이 다시금 연주된다.",
  str_pet_skin_desc_1600023 = "이미 생산이 중단된 일루미나 사관학교의 구형 생도복이다. 트렌치코트와 몸에 잘 맞는 작전복은 순시를 나선 히이로가 다양한 온도와 환경에 적응할 수 있도록 돕는다. 원래의 바지통은 히이로에게 조금 불편했기 때문에, 돌발 상황에도 더 쉽게 대처할 수 있도록 그녀는 어쩔 수 없이 가죽을 기워 몸에 잘 맞게 수선했다. 빨간 스카프 완장은 아마 그때부터 그녀의 변함없는 의지를 보여주고 있었던 것 같다.",
  str_pet_skin_desc_1600113 = "시로나가 비밀 장소에 갈 때 입는 복장이다. 동료의 말에 따르면 매년 이 시기마다 시로나는 이 복장을 입고 아무도 모르는 곳으로 향한다고 한다. 단정한 분위기의 스카프, 백야성 귀족의 스타일이 가미된 프릴, 일체감을 살린 발목 장식... 그 모습은 마치 그녀가 성대한 연회에 참가하러 가는 게 아닐까 생각하게 만들지만, 굳게 찌푸린 그녀의 두 눈썹은 그것이 결코 사실이 아님을 말해주고 있다.",
  str_pet_skin_desc_1500334 = "운앵 여관에서 제공하는 운산 특유의 복장으로, 바이스의 신체 구조에 맞게 임시로 개량된 여성용 유카타다. 간결한 배색, 독특한 허리띠와 노리개, 그리고 귀여운 방울까지... 모두 바이스가 평소와는 다른 분위기를 선보이도록 한다. 그녀는 이 유카타를 입을 때마다 잊지 못할 소중한 추억을 떠올리곤 한다.",
  str_pet_skin_desc_1500423 = "「시로 상사! 하쿠 상사!」 「잠수, 숨을 참는다!」 바튼은 혼자서 중얼거렸다. 그는 바다를 정복할 준비를 하고 있다. 시원한 흰색 와이셔츠, 항해에 적합한 스트라이프 셔츠, 변덕이 심한 바다의 날씨에 적응할 수 있는 코트... 이미 빛이 바랜 일루미나 마크 군모도 빠질 수 없다. 이 모자는 바튼이 결코 한가한 휴가를 즐기는 것이 아니라, 일루미나의 어떤 군사 임무에 참여하고 있음을 말해주는 듯하다.",
  str_pet_skin_desc_1400853 = "강렬한 상의와 우아한 치마가 결합된 기묘한 의상. 우울함과 순수함, 기이함과 아름다움이 뒤섞여 있다. 정교하게 짜인 소매, 분위기 있는 베일, 그리고 멋들어진 부츠... 제인의 옷차림은 보는 이들을 놀랍게 만들었다. 또한 그녀의 드레스에 피어난 꽃에도 숨은 뜻이 있는 듯하다. 다만 항상 아웃사이더를 자처했던 그녀는 어째서 이런 의상을 입은 것일까.",
  str_pet_skin_desc_1600253 = "어두운 밤에 강림하는 흡혈귀, 불바다의 뱃사공. 카론이 직접 제작한 블랙&레드 톤의 화려한 공연복이다. 클래식하고 로맨틱하면서, 기이하고 매혹적인 이 모습은 오직 이번 성대한 연극을 위해 준비됐다. 그는 감독이자, 작가 겸 주연 배우다. 부디 잔을 들어 그에게 환호를 보내 최고의 순간을 함께 맞이하자.",
  str_pet_skin_desc_1400573 = "이것은 오후의 달콤한 꿈이었다. 필리시는 푹신한 잠옷을 입고 침대에 웅크리고 잠들었다. 그녀는 유미가 곁에 있는 꿈을 꾸었고, 유미를 껴안고 머리를 쓰다듬어주었다. 그 꿈은 따스한 작은 난로처럼 그녀의 몸과 마음을 따뜻하게 만들었고, 모든 것이 마치 그때로 시간이 돌아간 것만 같았다.",
  str_pet_skin_desc_1500923 = "「...그렇게 뚫어지게 쳐다보지 마...!」\n이보다 더 난처한 순간이 있을까. 얽힌 가시덩굴이 펙트의 두 발을 들어 올렸고, 얇은 실크 스타킹과 검은 천은 조각조각 찢겨졌다. 다행히 이 혼란 속에서 펙트는 손에 든 와인 잔의 균형을 간신히 유지했다. 이 단정하면서도 화려한 드레스는 아무래도 생각보다 관리가 쉽지 않을 것 같다.",
  str_pet_skin_desc_1401023 = "이 단순한 복장은 「타오르는 불꽃」의 정신을 드러내고 있다. 이는 어두컴컴한 지하 격투장을 밝히는 유일한 환한 빛이었다. 도전자는 무대에 올라 근육과 육체, 정신과 의지를 겨루고, 선혈은 맹렬한 불길처럼 타오른다. 그러나 모든 것은 불길처럼 힘차게 타올랐다가 잿더미처럼 사라져 버린다. 손가락 관절을 푸는 그녀의 모습은 이미 눈앞의 모든 것을 사냥할 준비가 된 듯하다.",
  str_pet_skin_desc_1600933 = "미자드는 휴식을 취할 때도 편안하면서 몸에 잘 맞는 섹시한 옷을 선호한다. 또한 언제든지 실험을 진행할 수 있도록 깨끗하고 단정한 흰색 코트도 필수품이다. 그녀가 진지하게 집중할 때면, 설령 쉬는 시간일지라도 자신의 휴식실에서 연구와 작업을 멈추지 않는다. 결국 그녀의 휴식실은 그 기괴한 연구실과 다를 게 없는 셈이다.",
  str_pet_skin_desc_1601113 = "해변에 도착하자 항상 울적해 하던 베릴도 눈에 띄게 편안해 보인다. 이 수영복의 스타일은 무척 심플하지만, 곧잘 베릴의 몸매를 드러내고 있다. 하지만 베릴은 이러한 점을 전혀 의식하지 못하고 모래성 쌓는 것에만 온 힘을 쏟을 뿐이다. 어쩌면 베릴에게는 그것이 바로 해변에 와서 얻은 가장 큰 수확일지도 모른다.",
  str_pet_skin_desc_1600013 = "호수의 표면은 거울과 같고, 가볍게 건드리면 잔물결이 일어난다. 나시리스라는 이름의 그 소녀는 커다란 모직 숄과 새하얀 머메이드 스커트를 입고 있다. 그녀는 오로라처럼 연회의 주인공이 되어야 했지만, 그 대신 혼자 거울 호수로 오는 것을 택했다. 이곳은 춥고 어둡지만, 소음과 화려함에서 벗어날 수 있는 그녀만의 고요한 낙원이다.",
  str_pet_skin_desc_1600014 = "「그대는 그 아름다운 흰 꽃을 아직 기억하는가. 고요한 호숫가에서 함께 살아가는 두 줄기의 꽃을.」\n「한 줄기는 속세를 떠난 수선화, 한 줄기는 순결한 백합.」\n「때로는 육체와 정신이 판이하기도 하고, 때로는 용모와 영혼이 하나같기도 하네.」\n「한 줄기에서 잎이 자라고, 한 줄기에서 꽃이 피노라. 아침 이슬을 함께 마시고, 그 뿌리는 서로 얽혀 있나니.」",
  str_pet_skin_desc_1600383 = "「대위기! 그로누가 장난감 상자에 갇혀버렸어!」\n새해를 축하하기 위해 그로누가 준비한 깜짝 선물이다. 장난감과 함께 상자에 들어간 그녀는 깜찍하고 귀여워 보인다. 빨간색과 하얀색 복장은 기념일의 분위기를 드러내며, 그녀의 기계 팔에도 나비 리본이 장식되어 있다. 하지만 그녀가 들고 있는 악의 넘치는 폭탄은 역시 사양하고 싶다...",
  str_pet_skin_desc_1500993 = "소파에 몸을 웅크리고 있는 아이리나의 모습은 그녀가 수줍어할 때에만 볼 수 있는 자태다. 드러낸 두 발과 아무렇게나 놓인 신발, 입고 있는 드레스는 이제 막 무도회가 끝났음을 보여준다. 마치 「신데렐라」처럼 우아한 마법의 드레스는 비록 시간과 함께 점차 사라지겠지만, 당신과 함께한 시간, 그 추억은 결코 사라지거나 빛이 바래지도 않을 것이다.",
  str_pet_skin_desc_1400453 = "쏟아지는 함박눈과 함께 추운 겨울이 다가왔다. 거리에는 아무도 다니지 않고, 따스한 노란색 불빛들만 깜박거린다. 만약 당신이 혼자 여행하는 사람이라면 길을 잃을까 걱정할 필요는 없다. 구석에 하얀 턱시도와 검은색 부츠 차림의, 반들반들한 헤어스타일과 우아한 매너를 지닌, 차분하고 정숙한 신사가 마차 곁에서 당신을 계속 기다리고 있을 테니 말이다.",
  str_pet_skin_desc_1600193 = "화염에 타버린 장미는 피어나는 자태 그대로 재가 되었다. 이 아름다우면서도 사악한 모습은 거울 속에 온전히 비치고 있다. 빅토리아는 거울에 비친 자신을 바라보고 있었지만, 찾아온 당신을 보고 그녀는 고개를 돌렸다. 화려한 드레스의 자락은 부드러운 선을 그리며 돌고, 깊고 그윽한 두 눈동자는 당신을 심연 속으로 잡아당긴다.",
  str_pet_skin_desc_1600263 = "존재의 의미, 허무에 대한 인식... 이 이상한 복장으로 갈아입은 후, 우리엘의 머릿속은 하루 종일 이해할 수 없는 질문이 맴돌았고, 그녀를 끝없는 생각에 빠지게 만들었다. 가상의 문학 세계에서 우리엘은 정답을 찾을 수 있을까. 비록 단정할 순 없겠지만, 적어도 당신이 해줄 수 있는 것은 그녀가 문학에 빠져 있을 때, 곁에서 함께 생각하고 느껴주는 것이다.",
  str_pet_skin_desc_1400543 = "엄숙함과 진지함, 그것은 나딘이 일에 임하는 태도다. 영원히 지치지 않을 것만 같은 그녀는 항상 노력하며 자신의 임무를 수행하고 있다. 비록 평소와는 전혀 다른 청춘의 분위기가 가득한 의상으로 갈아입었다 해도, 들고 있는 등불에도 귀여운 장식이 더해졌다 해도, 그녀의 성실한 태도를 가릴 수는 없다.",
  str_pet_skin_desc_1500883 = "파란 하늘, 흰 구름, 평평한 거리, 평소의 레디젤 사막과는 완전히 다른 풍경. 마지도 평소의 자신과는 다른 모습이다. 그녀는 깔끔한 세일러복을 입고 있고, 커다란 나비 리본은 바람에 흔들리고 있다. 맑은 아침, 빵을 물고 「유유」하게 자전거를 타는 그녀의 모습, 학교에 늦기라도 한 걸까? 이 멋진 옷차림은 레디젤 렌치의 관객들에게 매우 독특한 인상을 주었고, 그녀 스스로도 평소와는 다른 풍경을 볼 수 있게 해주는 듯하다. 어쩌면 그것이 바로 옷이 지닌 마력일지도 모른다.",
  str_pet_skin_desc_1600963 = "「서, 선생님? 샤리 씨야?」\n샤리는 이 아르바이트를 매우 진지하게 생각하고 있는 것 같다. 그녀는 이번 일을 위해 특별한 제복으로 갈아입었다. 지금의 샤리는 평소보다 훨씬 믿음직해 보이고, 말투도 온화하면서 무게감이 느껴진다. 아마도 이번 수업에서는 그녀에게 정말 무언가 「지식」을 배울 수 있을 것 같다.",
  str_pet_skin_desc_1601053 = "평범한 복장을 입고 있어도 이브는 레디젤 렌치의 최고 인기인이다. 그러나 그녀가 얼마나 인기가 있는지는 그녀 자신도 잘 모르는 것 같다. 모두를 응원하기로 마음먹은 그녀는 어디서 왔는지 알 수 없는 이상한 복장을 입었지만, 인기는 오히려 하늘을 찌를 만큼 높아지고 말았다. 다만 그녀를 빤히 쳐다보거나 하지 않는 게 좋을 것이다. 하늘에서 거대한 렌치가 떨어질지도 모르니 말이다.",
  str_pet_skin_desc_1600064 = "하늘하늘하고 매끄러운 실크 리본이 잔뜩인 이 옷이... 파자마라고?! 어째서 이런 상식을 초월한 디자인의 옷이 존재하는 거지? 이런 옷을 정말 사람들 앞에서 입어도 되는 건가? 카렌은 고민에 빠졌고, 어쩔 줄을 몰랐지만 우선 입어보기로 했다. 그러자 항상 지적이고 엄격한 분위기의 카렌에게 전혀 다른 분위기가 드러나게 되었다.\n파자마 파티에 참가하고, 모두와 잘 어울리기 위해 카렌은 과감한 모험을 해보기로 했다.",
  str_pet_skin_desc_1600303 = "칠흑 같은 옷에 새빨간 외투, 이른바 천하의 악인을 모조리 베는 무사, 아카나미 사메노스케 등장!\n레디젤 렌치의 대장인 사메야마는 「다른 지방에 가면 그곳의 풍속을 따른다」는 수칙을 몸소 실천했고, 입고 있는 옷뿐만 아니라 허리에 찬 검까지 모두 완벽하게 운도의 정취를 드러내고 있다. 심지어 웃음소리마저 더 호쾌해진 듯한 느낌마저 든다. 하지만 주의해야 할 점은, 이 낭인 무사는 기분이 좋아지면 즉흥적으로 하이쿠를 지어 큰 소리로 노래를 부를지도 모른다는 것이다...",
  str_pet_skin_desc_1400443 = "상쾌한 바람이 소나무 숲에 불고, 온화한 햇살이 방안을 비춘다. 도시의 소란과 번잡한 업무에서 벗어나 고요한 「운산 여관」을 찾아온 이상, 잠시 휴식을 취할 기회를 놓칠 순 없다. 「워라밸」이야말로 비비안의 신조, 이곳의 일일 점장이 되어 몸과 마음을 편하게 하면. 다시 일할 의욕도 가득해질 것이다.\n물론 이것도 모두 비비안이 세운 계획의 일부다.",
  str_pet_skin_desc_1600643 = "레이스의 새로운 전투복으로, 동방의 명주실로 짜인 천은 가볍고 몸에 잘 맞으며, 아름답게 찰랑대고 있다. 비록 조금 얇아 보이지만 움직이기 편해서 레이스의 전투 능력에 조금도 영향을 미치지 않는다.\n주먹과 발을 마음껏 움직여 용감하게 전진하고, 모든 적을 쓸어버린다. 그 어떤 위험이 닥치더라도 믿음직한 레이스는 언제나처럼 모두 해결해줄 것이다.",
  str_pet_skin_desc_1600893 = "드물게 휴가를 얻은 이리돈은 특별히 운도 스타일의 옷을 준비했다. 금빛 천과 자수에 새하얀 모피 숄을 더해 우아함과 화사함이 느껴진다. 이리돈은 이 옷을 입고 운도의 거리를 거닐거나, 열차를 타고 명승지를 둘러볼 생각에 부푼 기대를 하고 있었다.\n그러나 갑작스러운 사건이 그녀의 계획을 방해했고, 모처럼의 휴가를 지키기 위해 이리돈은 운도의 기차역에서 심판소를 개정하는 것도 마다하지 않았다.",
  str_pet_skin_desc_1300653 = "「오빠야, 퍼뜩 지랑 깃털공 치입시더!」\n잔뜩 신이 난 트위티가 깃털공과 나무채를 들고 달려왔을 때, 그 얼굴에는 필승의 미소가 드러나 있었다. 처음엔 분명히 단순한 놀이라고 생각했는데, 갑자기 절대고수들의 강력한 대결로 변모?! 화려한 서브와 강력한 스파이크, 이미 일반인은 참가할 수 없는 수준의 경기가 되고 말았다!\n패자는 벌칙으로 얼굴에 낙서를 당한다는데, 부디 트위티가 자비를 베풀어 낙서를 조금만 했으면 좋겠다...",
  str_pet_skin_desc_1600233 = "친구들이 모두 「자동차 경주」에 참가하는 것을 본 코놀리는 이에 관심이 생겼고, 비록 부끄러웠지만 치어리더 참가 제안을 받아들여 모두의 응원을 맡게 되었다. 하지만 그녀의 일상복과 비교하면 이 치어리더 유니폼은 조금 「특별」했다.\n그럼에도 불구하고 자신이 더 활기차고 쾌활해지길 바란 코놀리는 어떤 상인이 제안한 이 자유분방한 복장을 수용했다.",
  str_pet_skin_desc_1500843 = "「모래의 뜨거움, 물의 온기와 부드러움, 레트로와 트렌디한 스타일의 겸비」\n「품위를 저버린 거칠고 예의 없는 언사... 무례하기 짝이 없군.」\n비록 평가는 다양했지만, 이스타반이 이 옷을 입고 나타나면 모든 부정적인 의견은 모습을 감춘다. 귀족의 대저택이 아니라도 품격을 느낄 수 있는 것, 어쩌면 그것은 「섀도우마스터」가 지닌 본연의 분위기일지도 모른다. 그리고 이 옷은 그에게 묘한 매력을 더하고 있다.",
  str_pet_skin_desc_1600603 = "레이싱 경기에서 심판의 옷은 언제나 유독 눈에 띄는데, 빠른 속도로 달리는 레이서들이 심판을 볼 수 있게 하려면 반드시 눈에 잘 띄어야 하기 때문이다.\n그저 술을 마실 돈이 없을 뿐이었던 요나는 이 경기의 심판 일을 맡게 된 후 경기에 숨겨진 비밀을 금방 알아차렸고, 평소 남의 일에 잘 간섭하지 않았던 요나는 한 소녀를 위해 경주로에 뛰어들었다. 그리고 이 부당한 경기를 꾸민 악당들에게 「정의」가 무엇인지 가르쳐 주었다.",
  str_pet_skin_desc_1500713 = "무더운 날씨, 혹독한 기후, 타오르는 태양 아래서 경주용 자동차는 연기를 내고 있고, 땀방울은 사막의 모래 위에 떨어져 한순간에 증발해 버린다.\n그러나 타키는 「완전 무장」을 하고 이 경기에 참가했고, 기회를 노리는 경쟁자들을 물리치고 단숨에 우승을 차지할 생각이다. 그를 이렇게 진지하게 만든 것이 과연 그저 돈 때문일까.",
  str_pet_skin_desc_1400613 = "「아... 대륙이 이런 모습이었군요!」\n구름 사이에 있는 찬드라는 고소공포증 같은 건 전혀 느끼지 않았고, 오히려 흥미진진하게 지상에서 펼쳐지는 랠리를 지켜보며 치열한 경쟁에 해설을 진행했다. 하지만... 이 열기구와 독특한 스타일의 복장은...\n사실 이 모든 것은 그녀의 신기한 「상상 치료법」의 일환일 뿐이었다. 그러나 이는 오랜 시간 쌓여 있던 타인의 마음속 부정적인 정서를 완벽하게 해소해 줄 수 있었다.",
  str_pet_skin_desc_1600103 = "「깔끔한 복장은 메이드의 자존심이죠!」\n그럼 리타가 직접 만든 메이드 복으로 갈아입고, 레이스가 달린 헤어밴드를 착용할게요. 아! 맞다, 금색 나비 리본이 달린 앞치마 매는 것도 잊으면 안 되죠.\n오늘 루이스는 주인님의 몸단장뿐만 아니라 애프터눈 티도 책임질 거예요. 걱정 마세요. 아기 꿀벌, 아기 순록, 구름 아저씨가 도와주러 올 테니까요.\n저길 보세요. 메이드 아가씨가 벌써 일을 시작했네요~",
  str_pet_skin_desc_1600283 = "「흠흠, 자, 여러분! 애플턴 저택의 메이드장님을 박수로 맞이해 주세요! 네? 낯이 익다고요? 맞아요, 잘 맞히셨네요. 바로 우리의 사랑스러운 라파엘이랍니다~」\n최근 라파엘은 특별한 임무 하나를 받았는데, 바로 백야성의 메이드들이 일정 수준의 전투 기술을 습득할 수 있도록 훈련시키는 것이었다. 이제 학기가 곧 끝날 시간이 되었고, 라파엘의 세심한 지도 덕분에 메이드들은 훌륭한 성적을 거두었다. 하지만... 정작 라파엘의 메이드 수행은 왠지 그리 순조롭지 않은 것 같다.",
  str_pet_skin_desc_1400673 = "산들바람이 불자 새하얀 치마가 가볍게 흔들리고, 사이에 수 놓인 붉은 꽃이 드러난다. 앨리스의 옷은 뭔가 케이크를 떠올리게 만드는 것 같은데... 그렇다. 바로 생일에 먹을 수 있는 딸기 케이크다. 하지만 「판타지 디저트 하우스」에서는 가게 주인인 앨리스의 질문에 성실하게 답하기만 하면 무료로 원하는 디저트를 맛볼 수 있다. 이건 앨리스가 주는 특별한 벌, 아니... 특별한 「보상」이다.",
  str_pet_skin_desc_1601163 = "플뢰르는 자신의 기억 속 「그 빵」을 만들기 위해 많은 고민과 시도를 해 왔지만 단 한 번도 성공하지 못했다. 그리고 그는 이번 도전을 위해 더 많은 준비를 했다. 깔끔한 봉재선의 셔츠, 잘 다려진 앞치마, 광이 나게 닦인 가죽구두까지... 이렇게 차려입으면 맛있는 빵을 만들 수 있다는 소문이 있기 때문이었다. 비록 그다지 신빙성은 없는 소문이었지만, 플뢰르는 마음속에 담아 둔 근심을 위해 그것을 믿기로 결정했다.",
  str_pet_skin_desc_1601263 = "창작의 슬럼프에 빠진 베스트셀러 작가, 영감을 얻고자 변장을 하고 거리로 나섰다. 변장을 하는 이유? 아마 평소 위엄이 넘치는 상회의 책임자에게 이런 「소녀다운」 취미가 있다는 사실을 알리고 싶지 않아서일지도 모른다.\n하지만 이 취미에 대한 베델의 집착을 결코 우습게 봐서는 안 된다. 번뜩이는 창작의 영감을 위해서라면 그녀는 어떠한 위험도 마다하지 않을 테니 말이다...",
  str_pet_skin_desc_1500703 = "이런 눈빛에 주시된다면 분위기가 뜨거워지고, 숨이 가빠지면서... 이건 긴장감일까? 아마 그럴 것이다. 강하면서도 아름다운 레오나 앞에서 긴장하지 않는 사람은 아마 거의 없을 것이다. 가느다란 레이스업 샌들은 그녀의 두 다리를 감싸고, 평소와는 사뭇 다른 액세서리들로 몸을 장식했지만, 그녀는 나른하게 세상 모든 것이 자신의 것이라는 듯한 분위기를 드러내고 있다.",
  str_pet_skin_desc_1400813 = "렉커가 「무언가」를 찾기 위해 특별히 준비한 의상이다. 활동이 쉬운 수영복, 자신만의 개성이 담긴 서프보드, 우비의 디자인을 참고한 투명 재킷... 투명 재킷? 이 투명 재킷을 준비한 렉커의 진짜 목적은 어쩌면 당신의 칭찬을 듣기 위해서일지도 모른다. 단백질 파우더와 고된 트레이닝, 햇살과 땀으로 빚어진 이 몸은 지금 이 순간 당신의 칭찬을 기다리고 있다.",
  str_pet_skin_desc_1601123 = "최근 움브라톤에는 한 전설이 회자되고 있다. 범죄 예고장... 모든 사람을 어쩔 줄 모르게 만드는 괴도... 도둑맞은 보석... 과연 의심을 받고 있는 이 용의자는 우리 앞에서 늘 무심하게 구는 그 스모키가 맞을까? 진실을 알고 싶다면 먼저 그녀의 수갑을 풀어줘야 할 것 같다. 물론 그녀의 새 칭호인 「검은 고양이 괴도」 또한 새로운 복장만큼이나 사람들을 궁금하게 만들고 있다. 그리고 그녀는 예고한 대로 3일 뒤에 보석을 훔치러 나타날 것이다.",
  str_pet_skin_desc_1600384 = "이 옷이 만들어지고 나서 그 게임이 생긴 걸까? 아니면 그 반대일까? 이 옷의 출처는 중요하지 않다. 중요한 건 그로누가 이 옷을 입고는 휴가 모드로 들어가 버렸다는 사실이다. 다시 말해서 그로누는 휴가를 위해 이 옷을 준비했다. 비록 이번 휴가에는 해변에 간 게 아니라 수족관을 구경했지만 말이다.",
  str_pet_skin_desc_1400413 = "그녀에게는 대체 몇 가지 신분이 있는 걸까? 그녀는 백야성의 안내자일 뿐만 아니라 여러 일을 겸업하고 있는데, 그중 하나는 심지어 「플라티나 선라이즈」 호텔의 홍보 대사였다. 이 수영복은 전단지에 쓸 사진을 촬영할 때 착용한 것인데, 원단과 재단 모두 무척이나 아름답다. 이 푸른 바다와 하늘 아래, 나도 모르게 그 호텔에 가 보고 싶어진다.",
  str_pet_skin_desc_1500873 = "한 섬에 있는 영지를 시찰하러 갔을 때, 현지 환경에 더 잘 어울릴 수 있도록 베벌리는 갑옷 모양의 이 수영복으로 갈아입었다. 평소의 옷차림보다 많이 간소해지기는 했지만, 귀족의 기품만은 전혀 바래지 않았다. 아마도 이는 무예를 숭상하는 가풍의 영향도 있기는 하겠지만, 그보다는 베벌리 자신이 귀족으로서의 명예를 추구하기 때문일 것이다.",
  str_pet_skin_desc_1601293 = "여름철 특유의 시원해 보이는 복장을 하고 있지만, 루크의 진지한 눈빛은 모든 이들에게 그가 여유를 즐기기 위해서가 아니라, 반드시 해야만 하는 임무를 완수하기 위해 이곳에 왔다는 사실을 잘 알려주고 있다. 이 옷차림은 루크가 습하고 더운 숲에서도 체력을 유지할 수 있게끔 해 줄 뿐만 아니라, 부끄러운 줄 모르는 밀렵꾼들에게서 진귀한 나비를 보호하기 위해 준비한 하나의 「예복」이다.",
  str_pet_skin_desc_1601483 = "사막 속 수상 축제가 곧 시작된다. 하지만 수많은 사람들을 유독 설레게 만드는 것은 바로 시선을 도저히 뗄 수 없는 아주르의 모습을 볼 수 있다는 것! 특히 그 얇디얇은 옷차림으로 두드러지는... 크흠, 그래도 너무 오래 쳐다보는 일이 없도록 시선을 주의하는 게 좋다. 이따금 따스하면서 습한 밤바람을 느끼며, 시끄러운 음악 속에서 북적이는 사람들과 함께 춤을 추는 것도 무척 즐거운 일이니 말이다!",
  str_pet_skin_desc_1600254 = "전통 있는 귀족적인 분위기, 화려한 무대 스타일... 이 의상이 일반적인 평상복과 전혀 어울리지 않는 것은 카론이 직접 디자인한 연극 의상이기 때문이다. 과해 보이긴 하지만 카메라 앞에 서면 가장 빠르게 관객의 시선을 사로잡을 수 있고, 카론이 자신을 잃어버릴 정도로 몰입하는 것을 도와주기에, 사람들에게 잊지 못할 연기를 선보일 수 있다. 이때의 카론은 이 옷과 연기를 위해 태어난 것이라고 해도 과언이 아닐 것이다.",
  str_pet_skin_desc_1400683 = "마케팅! 마케팅! 최근 쿠리어 길드는 움브라톤의 신문사와 제휴를 맺었고, 그로 인해 쿠리어는 어쩔 수 없이 새로운 임무를 맡게 되었는데, 바로 신문 구독을 권유하는 것이었다. 그렇게 웬디는 아동복을 입게 되었는데, 이런 모습으로 신문을 들고 다니면 판매가 매우 쉽기 때문이다. 신문과 함께 날아다니는 웬디의 모습을 보니, 새로운 업무라 해도 속도를 추구하는 웬디의 정신은 절대로 그녀를 뒤처지게 하지 않을 것이다.",
  str_pet_skin_desc_1501003 = "과거에 얽매여 있던 스칼렛, 이제는 다른 옷으로 갈아입었다. 언뜻 평범해 보이는 의사지만, 들고 다니는 의료 상자는 결코 평범하지 않은 그녀의 「작업 내용」을 알게 해준다. 그녀는 환자의 병을 돌볼 뿐만 아니라, 죽은 사람에게도, 「무덤」에서 나오는 소리에도 차별 없이 일해야 하기 때문이다...",
  str_pet_skin_desc_1601203 = "이것은 쌍방의 우호를 위해 개최하는 교류 행사이다. 백야성의 헤이디는 초대를 받아 일루미나 연방의 자난성으로 향했고, 교통안전과 범죄 예방을 홍보하는 「일일 치안관」이 되었다. 이로 인해 비록 백야성의 기사지만 헤이디는 명령에 따라 일루미나의 제복을 입었다. 비록 조금은 어색한 듯했지만, 그녀만의 자신감과 매력에는 전혀 영향을 주지 않았다.",
  str_pet_skin_desc_1601193 = "추억 속의 잊을 수 없는 맛을 찾기 위해 레비는 위험을 무릅쓰고 감옥에 들어가기로 결심했다. 그곳은 회색지대에서 활동하는 범죄자들로 가득 찬 위험한 곳이었다... 일루미나 연방에서 이 혼란스러운 땅에 처음으로 발을 딛은 레비, 그녀는 이곳에서 자신의 목표를 순조롭게 달성하고, 특별한 개인 잠입 임무를 완수할 수 있을까.",
  str_pet_skin_desc_1601194 = "그로누는 한 새로운 장비를 개발했는데, 이는 사용자를 아이들의 상상 속 히어로로 만들어 줄 수 있다고 했다. 이에 궁금해진 레비는 곧바로 그로누가 준비해 둔 방으로 향했다. 그녀는 그로누가 준비한 옷으로 갈아입었는데, 이는 헬멧이 달린 일체형 복장으로, 레비처럼 앙증맞은 여자아이만 입을 수 있었다. 그리고 레비는 그로누가 준비한 하이테크 제품 「암귀 청소기」까지 챙기고, 히어로로서 자신의 여정을 시작하게 되었다.",
  str_pet_skin_desc_1601173 = "온몸이 상처투성이임에도 홀로 연못에 서 있는 그람, 그는 여전히 자신의 특훈을 계속하고 있었다. 그에게 상처란 훈장이자 명예였고, 주변에 세워진 무기들은 그가 전장에서 겪어 온 파란만장한 세월의 증거였다. 전사는 결코 쓰러지지 않는다.",
  str_pet_skin_desc_1600234 = "바다의 숨결이 가득 담긴 화려한 드레스, 다채롭고 아리따운 장식들... 이 옷을 입은 코놀리는 마치 바닷속 요정으로 변신한 것처럼 보여서, 이제 더는 구석으로 숨어 남들 눈에 띄지 않는 것은 불가능한 일이 되었다. 비록 코놀리는 이 드레스를 그저 잠깐 빌리는 것뿐이고, 꿈속의 물건에 집착해선 안 된다고 했지만, 보이지 않는 세 명의 동료들은 오히려 그녀가 환상 속에서 얻은 것들을 현실로 가져올 수 있을 것이라 생각했다. 그녀의 사랑과 용기가 그랬듯이 말이다.",
  str_pet_skin_desc_1400163 = "당신과 함께 체력 훈련을 하던 카프카는 진작에 훈련 임무를 끝낸 뒤였다. 이 뜨거운 사막에서 카프카는 딱 봐도 시원해 보이는 옷을 입고, 차광막 아래에서 휴식을 취하며 프란츠와 놀고 있었다. 그녀는 틈틈이 이쪽을 쳐다봤는데, 당신을 걱정하고 있다는 것을 알 수 있었다.",
  str_pet_skin_desc_1501653 = "강화복과 함께 무너진 동굴 속에 갇혀버린 시엘, 동굴의 틈 사이로는 눈꽃이 내려오고 있었다. 다행히 시엘이 입고 있던 일루미나 작업복에는 방한 보온 효과가 있었다. 게다가, 로봇 내부에는 미약하게나마 빛이 남아 있어서, 시엘은 계속해서 그녀의 작업을 이어 나갈 수 있었다. 다만 한 가지 불편한 점이라면, 로봇의 내부 공간이 너무 작은 탓에 시엘이 두 발을 뻗을 수 없었다는 것이다.",
  str_pet_skin_desc_1601213 = "붉은 꽃, 가시로 뒤덮인 가지... 파로마의 복장은 낯선 이의 접근을 금지하는 분위기로 가득하며, 그 얕은 미소는 위험하고 매혹적인 기질을 더욱 강조한다. 만약 실수로 그녀를 화나게 한다면, 좋은 결말은 없을 것 같다는 생각이 든다. 마치 전설적인 움브라톤 클랜의 보스가 상대를 처리하는 것처럼 말이다. 어쩌면 지금 그녀는 이미 그 보스일지도...",
  str_pet_skin_desc_1500123 = "자난성에서 「정의 집행 a.k.a. 저지먼트」에 관한 전설이 갑자기 퍼지기 시작했다. 누군가 규율을 어길 때마다 고막을 찢을 듯한 거대한 천둥소리와 함께 네메시스가 그 앞에 나타나, 번개로 벌을 내린 뒤에 펀치라인으로 상대가 자신의 죄를 뉘우치도록 이끈다는 것이다. 「정의」를 집행한 사자는 천둥 속에서 홀연히 모습을 감춘 뒤 다른 곳으로 이동한다고 한다.",
  str_pet_skin_desc_1600773 = "베들레헴과 당신은 샤야의 오래된 노트를 발견했다. 샤야는 자신의 사명을 알고 있었고, 그래서 적어도 마지막 기한이 다가오기 전까지 그녀는 다른 미래를 상상하고 싶었다. 화가, 시인 또는 가수가 되는 미래를... 그것은 오직 그 순간밖에 꾸지 못하는 백일몽이었다. 하지만 두 사람이 이야기를 다 읽기도 전에, 낡은 노트는 세월의 침식을 받아 조각조각 부서져 버렸고, 아름다운 과거, 상상에 찬 미래와 함께 사라져 버렸다.\n「...어쩌면 그녀는 다른 미래를 가질 수도 있을 것이다.」 베들레헴은 아스트라 대륙에서 성공한 가수에 대한 정보를 당신에게 물었고, 그녀는 그것을 소재로 샤야의 꿈을 다시 써 주고자 했다.",
  str_pet_skin_desc_1400833 = "자신들이 지키는 「리리」를 깨우기 위해 그녀들이 할 수 있는 건... 아이돌이 되는 것? 하지만 단조로운 메이드의 규칙을 줄곧 지켜온 그녀들이 과연 아이돌 생활을 감당할 수 있을까? 아이돌이라는 것은 지칠 줄 모르는 에너지와 개성을 갖춰야 하는 법. 하지만 표준적인 프로세스가 있다면, 여기에 다양한 멤버로 구성된 그녀들의 장점을 더한다면 어쩌면 정말로 가능할지도 모른다...",
  str_pet_skin_desc_1601313 = "비록 다른 견해를 가지고 있긴 했지만, 노비오는 이날이 되면 여전히 평소와 다른 옷을 입고, 순식간에 피아니스트의 모습으로 변한다. 북방에서 힘겹게 살아가는 사람들에게 온기와 축복을 전하고, 희망을 간직한 사람들이 앞으로도 흔들리지 않고 자신의 길을 씩씩하게 나아가는 것을 응원하기 위해...",
  str_pet_skin_desc_1601383 = "상사가 억지로 참여시킨 아이돌 오디션이지만, 그래도 시오반은 착실히 여러 준비를 했다. 개인기를 갈고닦으며, 의상의 연구와 디자인에도 아낌없이 상당한 열정을 투자했다. 그리고 이 연구 정신은 시오반을 그 누구보다도 찬란하게 빛나는 전도유망한 스타로 탈바꿈시켜 주었다.",
  str_pet_skin_desc_1600273 = "백야성 연인들 사이에서는 무서운 전설이 전해지는데, 매년 관월제가 되면 흰옷을 입은 기사가 백야성 구석구석을 돌며 열애 중인 사람들을 찾아내서, 「연애 금지」 처벌 통지서를 내민다고 한다. 때문에 그녀는 연인들로부터 「사랑을 끊는 뇌광」으로 불리며 두려움의 존재가 되었다.",
  str_pet_skin_desc_1500553 = "평소의 엄숙한 옷차림과 달리 오늘의 피트만은 거리의 관월제 분위기에 영향을 받았는지, 여느 때의 의연한 분위기를 잃지 않으면서도 흔치 않은 다정함을 품고 있다. 물론 이는 그가 마음에 품은 사람을 만나기 위해서 준비한 것이 아니라, 다른 이의 염원을 이루어 주기 위한 사자로서 어울리는 복장을 선택한 것이다.",
  str_pet_skin_desc_1400913 = "크로이에게 사랑은 언제나 이별과 함께하고 있다. 그런 그녀에게 행복이 가득한 사랑을 찬양하는 곡을 연주하게 하는 것은 조금 무리가 있을지도 모른다. 그렇다면 차라리 신의 이름으로 영원한 사랑을 노래하는 것은 어떨까. 사람들이 품는 사랑은 한정된 세월과 함께 스러진다. 하지만 그것 또한 무방한 일이다. 빛은 언제나 평등하게 이 세상의 모든 사람을 축복하고 사랑해 줄 테니 말이다.",
  str_pet_skin_desc_1601673 = "이 사교 장소에는 다양한 마술이 존재하는데, 그 핵심은 바로 「비밀성」이다. 카드 한 장, 말 한마디, 한순간의 눈빛, 술잔이 오가는 찰나의 순간, 성대하고 절묘한 퍼포먼스는 이미 완성되어 있다. 비록 평소와 같은 박수갈채는 들려오지 않지만, 친구를 위해 인정을 베푸는 제노의 모습도 나쁘지 않은 것 같다.",
  str_pet_skin_desc_1600043 = "차가운 시신, 표시된 단서, 겹겹의 경계선들... 이 고전적이면서도 긴장감 넘치는 현장은 항상 사람들에게 무한한 상상을 불러일으킬 것이다. 예를 들어 형사가 범인이라거나, 이미 범인과 오래전부터 공모했다거나... 어쩌면 범인은 우리 사이에 있거나, 모든 증인이 범인일지도 모른다거나 하는 생각들 말이다. 하지만 희생자와 탐정이 애초에 한 팀이었다는 것은 누가 생각해낼 수 있을까?",
  str_pet_skin_desc_1400483 = "움브라톤의 평화로운 거리에 불길한 기운이 서서히 피어나고 있다. 지나가는 행인들은 고요한 밤을 즐기는 듯하지만, 오직 순찰대원의 경계하는 눈빛은 범죄의 흔적을 결코 놓치지 않는다. 놈들이 이 도시에 숨어 있는 한, 평화를 지키는 그녀는 결코 그 발걸음을, 순찰을 멈추지 않을 것이다. 그리고 이 모든 것은... 그녀의 하나뿐인 여동생을 위한 일이다.",
  str_pet_skin_desc_1601484 = "밝고 깨끗한 창문이 있는 사무소, 푹신한 소파, 흠뻑 취하게 만드는 멋진 와인, 그리고 소파에 누워 있는 「임시 대표」... 그녀의 게으른 태도에 속아서는 안 된다. 이 아름다운 여인은 무척이나 위험하며, 특히 곧 찾아올 사냥감에게 있어서는... 말 그대로 「위험」 그 자체라 할 수 있다.",
  str_pet_skin_desc_1601663 = "「음... 그 귀여운 녀석들은 어디 갔을까?」 환상동물들을 찾고, 진상을 밝히기 위해 피아는 탐정으로 변신해서 이 「미스터리 사건」을 조사하기 시작했다. 찾아낸 각종 증거들을 상세하게 조사하면서, 그 속에 담긴 핵심 의문점을 생각하는 그녀의 진지한 모습을 보면, 왠지 정말로 뭔가를 발견할 수 있을 것 같다는 생각이 든다.",
  str_pet_skin_desc_1500983 = "항상 집에만 틀어박혀 있었던 쿠스쿠타도 섀도우마스터의 명령 때문에 어쩔 수 없이 탐정으로서 최근 날뛰는 범죄자 체포에 나설 수밖에 없었다. 물론, 쿠스쿠타는 현장 심문이나 증거 탐문에는 그리 능숙하지 않을지도 모른다. 하지만 예리한 그녀는 가지고 있는 단서만으로 「안락의자」에 앉아 체스판을 바라보며 깊은 생각에 잠긴 끝에 범인을 추리해낼 수 있었다.",
  str_pet_skin_desc_1601034 = "세상 사람들은 죄를 저질러서는 안 된다. 죄를 지으면 하늘의 벌을 받기 때문이다. 그 벌은 세상에서 심문, 판결, 처벌의 형태로 구현되나, 그 과정은 사실 그리 무섭지 않다. 특히 심문 전문가인 엘시는 무척이나 상냥하며, 그 어떤 폭력을 사용하지 않는다. 그저 상대방의 마음의 문을 열 뿐... 물론 그 마음의 문이란 저항은 애초부터 아무 의미가 없을지도 모른다. 따라서 만약 당신이 엘시를 만나게 된다면, 저항하지 말고 모든 것을 그녀에게 맡기는 편이 나을 것이다.",
  str_pet_skin_desc_1400623 = "리아가 개최한 스터디 모임의 순조로운 진행을 위해 실바는 특별히 이 정장으로 갈아입었고, 그 모습은 마치 곧 선생님을 만나러 가는 젊은 학자처럼 총명하고, 지혜롭고, 단정하다. 그의 태도는 자연스럽게 스터디 모임에 좋은 분위기를 가져왔고, 따라서 굳이 표현하자면 그는 「모범생」이라고 할 수 있을 것이다...",
  str_pet_skin_desc_1300463 = "어른들에게는 무시무시한 흑마법서지만, 녀석들에게는 신비한 세계로 들어가는 입구일 뿐이다. 그곳은 환상과 마법, 불가사의가 가득한 곳으로, 녀석들처럼 호기심 많고 외로운 영혼들을 위해 준비된 곳이다. 그리고 녀석들은 그 「금단의 마법약」을 만들어 내기 위해 사방에서 온갖 기괴한 재료를 모으고 전문적인 복장으로 갈아입었고, 그 모습은 녀석들을 더욱 특별하게 만들었다.",
  str_pet_skin_desc_1600293 = "그 「마스터」의 유언을 들어주기 위해, 가브리엘은 이 엄숙한 드레스를 입고 움브라톤에 있는 그 고아원으로 향했다. 어두컴컴하고 낡은 환경은 정교한 복장과 선명한 대비를 이루었고, 가브리엘의 무딘 표현은 고아들이 그녀를 「마녀」로 오해하게 만들었다. 그러나 끝내 고아들은 이곳을 지키려는 가브리엘의 마음을 느낄 수 있었고, 마침 이 드레스는 마음을 위로하는 작은 빛을 발하고 있는 것 같았다.",
  str_pet_skin_desc_1601433 = "숲속의 밤놀이, 갑자기 내리는 뇌우, 일설에는 불길한 존재가 현세를 배회하고 있는 것이라고 한다. 때문에 린네는 엄숙한 무녀복을 입고 신악의 방울을 높이 들어, 부정함을 제거하고 중생을 지키고자 한다.\n「이제 음양을 읊노니, 이 곡조와 함께 그대의 혼은 피안으로 돌아가리라.」\n「삼도의 강물 아래에서 곡의 유생을 원망할지니.」\n「만다라가 부르나니, 금슬은 합하여 울레라.」\n「듣는 이의 넋을 달래노니, 혼백이여 스러질지어다.」",
  str_pet_skin_desc_1601214 = "이 옷차림의 파로마는 관능적이면서도 신비로운 매력을 발산하여 사람들을 매료시키며, 그 매력에 저항할 수 없는 이들은 그녀를 여신으로 추앙하고 무릎 꿇어 숭배한다. 그러나 파로마가 가장 싫어하는 것은 바로 그런 맹목적인 숭배다. 날카로운 가시가 자란 꽃처럼, 그녀는 맹목적인 신앙의 어리석음을 파헤칠 뿐만 아니라, 제멋대로 그녀에게 다가오려는 자들에게 고통을 선사한다.",
  str_pet_skin_desc_1601054 = "허구의 꿈의 세계는 사라지고, 진실한 사랑과 그 하얀 꽃을 찾는 그녀는 아픔을 당당하게 마주하기로 결심했다. 거짓된 행복과 아름다운 꿈으로 엮인 새장을 깨트리고, 더는 누구의 꼭두각시나 체스말 노릇도 하지 않을 것이다. 그리고 그녀는 비로소 자신의 꿈을 이루었다. 「진짜 햇빛」을 온몸으로 느끼며, 「진짜 꽃밭」 속을 달려 작은 소원을 비는 것 말이다.",
  str_pet_skin_desc_1601403 = "한 해저 유적을 조사하기 위해 플로리나는 직접 깊은 바닷속으로 잠수했다. 시간이 긴박한 탓에 그녀가 찾아낸 건 이 기괴한 수영복뿐이었다. 디자인이나 재질로 봤을 때 이 수영복은 아무래도 다른 유적에서 찾아낸 것 같다... 왠지 모르게 플로리나의 기괴한 평소 복장과도 잘 어울리며, 딱 보기에도 같은 유적의 유물인 모양이다.",
  str_pet_skin_desc_1601153 = "쿠리어 길드는 언제나 바쁘다. 항상 바쁘게 일해 온 나로세르라 해도, 아무리 노력하고 애써도 수습이 안 되는 순간이 있기 마련이다. 기분 전환을 위해 그녀는 여름의 잔교가 놓인 바다로 향하기로 결정했고, 끝없이 이어지는 바다와 하늘의 색을 감상하며, 모래 냄새가 가득한 바닷바람의 향을 느꼈다. 그 모습을 보면 그녀가 지금 이 순간의 고요함을 무척이나 즐기고 있음을 알 수 있다.",
  str_pet_skin_desc_1400793 = "레디젤 사막에 온 미제니는 현지의 환경에 녹아들고, 남들의 주목을 피해 불필요한 소동에 휘말리지 않도록 시원한 옷을 선택했다. 어쨌든 이곳은 문명의 도시 백야성이 아니라 거친 야생의 사막이기 때문이다. 그리고 미제니를 이런 위험한 사막으로 홀로 향하게 만든 것은 바로 한 특별한 고양이였다...",
  str_pet_skin_desc_1600774 = "북방의 얼음과 눈은 베들레헴을 위해 차가운 셉터를 주조했고, 두꺼운 코트를 짜주었다. 그러나 그 모습의 베들레헴을 볼 때마다 사람들은 생각하곤 한다. 과연 겨울이 가고 봄을 지나, 뜨거운 여름이 오면 그녀의 차가운 가면도 녹아내릴지, 여름밤의 바닷바람이 불어오면 그녀가 날개를 펼치고, 모든 생명이 피어나는 듯한 미소를 지을지 말이다.",
  str_pet_skin_desc_1601783 = "금화는 산더미처럼 쌓여있고, 보물은 온 땅에 흩뿌려져 있다. 전설 속 최후의 우로보로스가 지키고 있던 신비한 보물이 갑자기 세상에 모습을 드러낸 것이다. 과연 저 용감한 모험가들은 손에 쥔 유일한 단서를 토대로, 모든 어려움과 위험을 이겨내고 보물을 찾은 다음, 그것을 지키는 우로보로스로부터 무사히 벗어날 수 있을까. 아니면 녀석의 뱃속에 집어삼켜질까.",
  str_pet_skin_desc_1501573 = "사나에는 니나가 전세를 낸 개인 박물관에서 눈을 떴다. 아직 졸음이 가시지 않은 그녀는 조금은 이상한 이 박물관을 떠날 준비를 하고 있었다. 그러나 그 순간, 곁에 있던 인형이 괴이한 미소를 지었고, 어둠 속에서 들려오는 발소리는 점점 더 가까워지고 있었다…",
  str_pet_skin_desc_1500563 = "긴 객지 여행을 떠났던 콘스탄틴은 오랜 시간 떠나 있던 고향으로 돌아왔다. 그는 단정한 옷차림을 하고 있었고, 손에 들고 있는 무기는 이미 표적을 노리고 있었다. 암귀, 아무리 많은 암귀가 있더라도 그는 한 마리도 남기지 않고 죽여버릴 것이며, 결코 과거의 비극이 이 땅에 다시 일어나는 것을 용납하지 않을 것이다.",
  str_pet_skin_desc_1602113 = "시간은 100년 전에 멈추어 있고, 모든 것은 그저 추억일 뿐.\n얕은 바다 위에 선 자리야, 여름 끝자락의 즐거운 여행이었어야 했지만, 흐린 하늘에서 내리는 비는 그녀에게 아쉬움뿐인 과거와 다시는 만날 수 없는 가족을 떠올리게 했다.",
  str_pet_skin_desc_1600894 = "이리돈은 아버지에 대한 복잡한 감정으로 인해 금빛 물결 아래의 꿈속에 빠져들었다. 그 속에서 그녀는 심판소에 갓 배속된 심판기사가 되어, 잠재의식이 안내하는 대로 아버지가 과거에 겪었던 사건을 다시 검토했다. 무엇이 진짜 공정이고, 무엇이 진짜 정의인가. 이리돈은 손에 쥔 검과 지팡이로 이 불락의 성을 지탱해 낼 수 있는 저울을 만들겠다고 맹세했다.",
  str_pet_skin_desc_1601563 = "호박 원석들을 옷처럼 만들어 입은 니나, 카메라의 밝은 빛과 함께 스포트라이트 아래 서 있는 그녀는 끊임없이 몸의 방향을 바꾸고 있다. 그 작은 변화 하나하나는 모두 니나가 보석 대회에서 우승할 수 있을지를 결정할 것이며, 이번에 그녀는 마치 보석처럼 반드시 그 누구보다 빛나야 한다.",
  str_pet_skin_desc_1400544 = "전설 속 용주의 등탑은 바람도 파도도 두려워하지 않고, 바다와 더불어 사는 모든 생명에게 온기와 위로를 전해준다고 한다. 그리고 지금 이 순간, 나딘은 바로 그 등탑의 화신이다. 밤이 찾아오고 바다에 안개가 끼기 시작하면, 나딘은 밝은 등을 손에 들고 희망의 등탑이 된다. 그렇게 망망대해 속 인도자가 되어 배가 무사히 귀항하도록 하고, 길을 잃고 지친 사람들에게 등불로 방향을 인도하며 축복을 전한다. 그리고 이것은 그녀 자신의 소망이기도 하다.",
  str_pet_skin_desc_1601883 = "열두 살의 소녀 단당은 선녀처럼 꿈속에서 춤을 추었다. 그 춤과 함께하는 것은 해수면의 반짝이는 빛이요, 뭇 산들이 굽이치는 듯한 파도였으며, 그 어렴풋하면서도 아름다운 모습은 이 꿈속의 소녀와도 같았다. 바람을 타는 배 또한 물고기 떼처럼 파도를 헤쳐 나가고 있었다. 그리고 미래의 그녀는 장차 자신의 꿈을 손수 이루고, 수많은 배에 실린 번영을 더 머나먼 곳까지 인도할 것이다.",
  str_pet_skin_desc_1600964 = "누구나 잘 아는 사정 때문에 샤리는 또 새로운 아르바이트를 구했다. 이번 일터는 많은 사람들로 붐비는 호화로운 카지노였다. 그 안에는 자신의 결과와 운세를 가지고 분통해하는 손님들로 가득했고, 알바비라면... 분명히 두둑할 것이다! 그러나 샤리가 입어야 하는 근무 복장은 무려 비대칭 디자인이 넘치는 드레스였다... 이 무슨 비인간적인 고문이란 말인가! 그렇게 어쩔 수 없이 드레스를 입은 샤리는 엉망진창인 아르바이트 경험을 시작했다.",
  str_pet_skin_desc_1600065 = "“다른 고장에 가서는 그곳의 풍속을 따라야 하는 법”, 우연한 인연 덕분에 카렌은 용주 대륙의 옷을 입게 되었는데, 의외인 점은 그녀에게 무척이나 잘 어울린다는 것이었다. 옷은 중후한 분위기를 자아냈고, 함께 받은 무기 또한 예상외로 카렌이 다루기에 무척 편했다. 그러나 이 옷차림의 카렌은 아무래도 협객으로 오해를 받고 말았는지, 「강호」라고 불리는 신비한 세계의 발을 들이게 되었고, 그곳에서 어느 불청객과 영문 모를 싸움에 휘말리게 되었다...",
  str_pet_skin_desc_1500335 = "머나먼 용주 대륙에는 한때 「용녀」의 전설이 전해졌는데, 날씨를 관장하고 항해가 평안하도록 지켜 주는 존재라고 한다. 이에 사람들은 특별한 시기에 의식을 거행해서 용녀의 은혜에 감사하고 그 공적을 기렸다. 의식에서는 춤 실력이 뛰어난 소녀가 특별한 의상을 입고, 전설의 용녀가 대해를 달래는 모습을 본떠 만든 아름다운 춤을 추게 된다.",
  str_pet_skin_desc_1601723 = "리리카는 한 고아원의 연극에 출연해 달라는 요청을 받았다. 그녀는 정성껏 차려입고 최고의 컨디션에서 아이들에게 성대하고 완벽한 퍼포먼스를 보여주고 싶었다. 이 연극을 위해 리리카는 자신을 기념일 분위기에 딱 맞는 캐릭터로 만들었고, 가장 적합한 공연 의상을 준비했다. 그러나 이 의상은 방한성이 조금 부족해 보인다. 부디 리리카가 감기에 걸리지 않기를...",
  str_pet_skin_desc_1501873 = "화려하고 웅장한 해저 용궁 속, 이천간은 느긋하게 아름다운 진주조개 의자에 앉아 있다. 몸에는 그가 마음에 들어 한 금은보화들이 잔뜩 달려 있고, 얼굴에는 만족스러운 미소가 드러나 있다. 그는 한때 정말로 심해의 용궁에 가서 손님 대접을 받은 적이 있다고 하는데... 당신이라면 그의 말을 믿을 수 있을까.",
  str_pet_skin_desc_1400733 = "아스트라 대륙의 두 마리 「문지기 강아지」는 이 이방의 땅에 온 뒤로 이곳 사람들에게 전설 속 「흑백쌍살」로 오해받게 되었다. 그러나 오해가 풀린 뒤에도 두 사람은 여전히 진짜인 양 연기하는 것을 즐기며, 사람들에게 겁을 주고 있다. 「흑살 파티를 만나는 자, 조심하고 피할지어다. 백살 파시를 만나는 자, 제물을 바치고 행운을 빌지어다.」",
  str_pet_skin_desc_1600024 = "운도 신산의 봉인에 이변이 생기자, 편지를 받은 히이로는 상황을 조사하러 가고자 했다. 일전에 운도를 떠나면서 운앵 여관의 할머니는 그녀에게 벚꽃 일족이 남겼던 옷을 전했지만, 히이로는 아직까지 그것을 입어본 적이 없었고, 여관 할머니의 마음에 정식으로 감사의 인사를 전한 적도 없었다. 이번 여정에서 그녀는 이 옷을 입고, 오랫동안 떨어져 있던 고향으로 당신과 함께 돌아가기로 결정했다.",
  str_pet_skin_desc_1601703 = "폴룩스는 당신에게 과거의 일을 이야기해 주었다. 그해, 한때 번성했던 유포리아는 황폐한 폐허로 전락했고, 그 처량한 광경 속에는 무기의 파편과 아이들의 울음소리로 가득했다. 폴룩스가 떠나간 이의 유지를 계승하고, 수호자로서의 무거운 책임을 감당하기로 결정한 것도 그해였다. 그리고 이제, 그녀가 지키려는 그 미래 안에는 당신이 있다.",
  str_pet_skin_desc_1500994 = "용주에서 온 그 고용주는 씀씀이가 호탕해 쌍사성 최고의 재봉소에서 아이리나를 위해 이 옷을 마련했고, 부드럽게 휘날리는 비단과 정교하게 더해진 장식은 피부의 결점을 잘 가려주었다. 그녀를 본 사람은 누구나 그녀를 규방에서 처음 나온 가녀린 아씨가 가문의 언니와 함께, 마음에 드는 가게를 찾고 있다고 생각할 것이다. 그리고 이 위장은 그녀가 잠입 및 조사 임무를 은밀히 수행하는 데 큰 도움을 주었다.",
  str_pet_skin_desc_1602163 = "전설 속 혼돈의 태고, 사람들은 별을 인도로 삼아 만물을 측량했다. 그러나 별은 너무나도 높고 멀리 있어, 아무리 발끝을 들고 두 팔을 뻗어 보아도 닿을 수 없었다. 이에 하늘은 땅의 모든 이들이 함께 품은 꿈이 되었다. 이제 선극은 별하늘의 한 귀퉁이를 떼어 우산에 달고, 그것으로 당신을 위해 비바람을 막아줄 작은 세계를 세워줄 것이다.",
  str_pet_skin_desc_1401273 = "어릴 적 파솔로의 소원은 부모님과 함께 사막을 떠나 나비를 보는 것이었다. 그러나 자란 후의 그녀는 줄곧 혼자만의 여정을 밟을 수밖에 없었고... 그 여정의 끝에서 당신을 만났다. 그리고 지금, 춘삭절의 시끌벅적함과 춤추는 종이나비 사이에서 당신과 그녀는 가족이 되기로 약속했다.",
  str_pet_skin_desc_1500093 = "문자는 진리의 불꽃이다. 문자가 있으므로 선인들의 지식은 보존되고, 축적되어 시간의 격류를 초월해 천 년 후에도 찬송되는 시로 변할 수 있었던 것이다. 서생 차림을 한 파우스트는 오늘도 쌍사성에서 문자와 진리의 오묘함을 탐구하고 있다.",
  str_pet_skin_desc_1600264 = "「조종사, 난 오로리안을 그만두겠어!」\n허무를 참을 수 없었던 우리엘은 마법약을 이용해 다른 존재로 변신하려 했다. 그러나 마법약을 마신 후 그녀는 그 소원을 이루지 못했고, 오히려 기묘한 만취 상태에 빠지고 말았다. 원래는 우울하고 냉담했던 그녀는 갑자기 적극적으로 변했고, 당신과 함께 특별한 일들을 시도하길 갈망했다. 이제 앞으로의 하루를 그녀와 어떻게 보내야 할까.",
  str_pet_skin_desc_1601753 = "「저 꽃이 시들어버리고 나면, 악셀리아는 완전히 부서질 것입니다.」\n전쟁에서 부상을 입고 병원 침대에서 깨어난 악셀리아는 침대 옆 유리병에 정성스럽게 보관된 장미 한 송이를 발견했다. 그 순간 그녀는 형용하기 힘든 감성적인 생각을 떠올렸고, 자신이 곧 폐기될 운명에 빠질 것이라 여겼다. 이 관월제 홍보용 장미를 그녀에게 선물했던 당신은 운명, 장미, 그리고 그녀와의 관계에 대해 잘 설명해 주기로 했다...",
  str_pet_skin_desc_1701073 = "「가장 유명한 평민 영웅을 우리 함께 환영합시다! 그는 셀 수 없이 많은 전투를 겪었고, 이번에도 무사히 돌아와 우리에게 승리를 선사했습니다! 자, 들어 보십시오! 온 도시의 귀족과 평민, 모두가 그의 이름을 외치고 있습니다! 아드라스, 아드라스! 우리의 영웅은 이제 곧 영광과 행복의 정상에 서게 될 것입니다!」",
  str_pet_skin_desc_1600114 = "예복을 입은 시로나는 유적을 배회하고 있다. 용의 조각상 아래에는 어쩌면 그녀의 고대 일족과 관련된 정보가 있을지도 모른다. 과연 그들은 이 미지의 용의 힘에 어떤 생각을 가지고 있고, 그 힘에 삼켜지는 자아에 어떤 의문을 품었을까. 고대의 맹세는 역사의 바람 속으로 사라지고, 강인한 장군조차 불안하게 만드는 지금, 당신은 그녀에게 새로운 맹세를 전하고, 다시금 신념의 불꽃을 피워줄 수 있을까.",
  str_pet_skin_desc_1401013 = "장난을 쳐서 사고를 친 안시아는 처벌로 의장대에 들어가 예절 훈련을 받게 되었다. 과연 그녀의 최종 훈련 성과는 어떨지 지켜봐 주자.",
  str_pet_skin_desc_1500783 = "움브라톤 구석에 있는 로빈은 편안하면서도 개성 있는 캐주얼 복장을 입고, 조용한 시간을 보내고자 한다. 하지만 늘 낯선 사람을 멀리하던 그녀가 당신을 먼저 집으로 초대한 이유는 무엇일까.",
  str_pet_skin_desc_1601164 = "손에는 방금 건진 부품을 쥐고 흥분하며 물 밖으로 나온 플뢰르, 머리카락 끝에는 물방울이 뚝뚝 떨어졌고, 그의 뜨거운 시선이 당신이 있는 곳을 향하고 있었다. 이 해 질 녘의 석양이 비치는 순간, 그의 가슴속에서 들끓는 감정은 과연 무엇일까.",
  str_pet_skin_desc_1601773 = "골디의 팬 추첨에 당첨된 당신은 그녀의 「일일 매니저」가 되었다. 그러나 바쁜 아이돌 활동만이 아니라 골디의 생활도 챙겨야 한다는데... 따스한 집으로 돌아와 귀여운 잠옷을 입은 골디는 마음속 감정을 당신과 나누고 싶어 했다.",
  str_pet_skin_desc_1500924 = "마침내 혼자서 임무를 수행할 기회를 얻은 펙트! 그녀는 다음 연회에 사용할 재료 조달을 전담하게 되었다. 수월한 일처리를 위해 그녀는 수년간 숨겨두었던 비상금을 꺼내 부티 나고 영리한 사업가로 분장했다. 이제 펙트를 과소평가했던 상인들도 더는 그녀를 잘못 보는 일이 없을 것이다.",
  str_pet_skin_desc_1601823 = "「비급의 설명에 의하면, 가장 맛있는 탕을 끓여낼 수 있는 우렁이는 바로 이 강 속에 있다고 해.」\n목월백과 당신은 숲의 강가에서 만나 함께 환상처럼 맛있는 우렁이를 찾았다.",
  str_pet_skin_desc_1602233 = "「그대를 위해 엮은 액막이 끈, 오색으로 천 개의 봄을 바라노라.」\n용주의 오색절, 당신과 진예는 「어떤 소원」을 찾는 모험을 떠났다. 세상 사람들은 누구나 바라는 것이 있는 법, 그리고 당신에게 다시 한번 선녀용왕 앞에서 두 손을 모아 기도할 기회가 주어진다면, 이번에는 과연 어떤 소원을 빌게 될까.",
  str_pet_skin_desc_1400403 = "봄버 존은 우연히 한 오래된 단어인 「BBQ」를 알게 되었다. 이는 매우 격렬한 조리 방법이라고 하는데... 주방이 날아가 버려도 정말 괜찮은 것일까.",
  str_pet_skin_desc_1500363 = "움브라톤의 거리, 휴라드는 무리에서 떨어진 늑대를 찾고 있었다. 그는 늑대 무리를 해치는 녀석들을 쓰러트리고, 몇 안 되는 「동료」를 지키기 위해 힘썼다. 늘 혼자이길 자처하던 그였지만, 어느새 타인과의 우연한 만남을 거부하지 않게 되었던 것이다. 늑대는 무리 생활을 하는 동물이다. 아무리 부인하더라도 휴라드 역시 예외는 아닐 것이다.",
  str_pet_skin_desc_1601993 = "푸른 하늘은 아득하고, 잡초는 지난날의 문명이 남긴 흔적과 얽혀 있다.\n새들의 울음소리는 마치 이 순간에 보내는 찬미가처럼 들리고, 늘 진지했던 잉겔도 스타일리시하면서 캐주얼한 의상으로 갈아입었다. 그녀가 길가에 서서 바라보는 것은 저 하늘일까, 아니면 저 새 떼일까, 그것도 아니면 우연한 만남을 기다리고 있는 것일까.\n흐릿한 바람은 두 사람의 시선을 이끈다. 자유의 노래가 아직 끝나지 않은 동안, 그녀와 함께 출발하는 것은 어떨까.",
  str_pet_skin_desc_1500424 = "헐렁하고 실용적인 짧은 재킷, 뻣뻣하고 내구성이 뛰어난 청바지, 가죽 재질의 짧은 부츠... 이것이 바로 바튼이 처음 군단에 합류했을 때 갖추고 있던 장비의 전부다.\n그가 원대한 포부를 지닌 병사에서 대군을 통솔하는 위엄 있는 장군으로 성장하는 과정을 지켜봐 온 것 또한 그 간소한 옷들이었다.",
  str_pet_skin_desc_1601553 = "헐렁하고 실용적인 짧은 재킷, 뻣뻣하고 내구성이 뛰어난 청바지, 가죽 재질의 짧은 부츠... 이것이 바로 바튼이 처음 군단에 합류했을 때 갖추고 있던 장비의 전부다.\n그가 원대한 포부를 지닌 병사에서 대군을 통솔하는 위엄 있는 장군으로 성장하는 과정을 지켜봐 온 것 또한 그 간소한 옷들이었다.",
  str_pet_skin_desc_1601843 = "따뜻한 바람이 부는 해변, 만약 수영복의 목적이 「마음의 문을 여는 것」이라면, 과연 어떤 놀라운 효과를 보여줄까?\n예리아는 왠지 착각 때문에 이 대담한 수영복으로 갈아입게 된 것 같았고, 당신은 해변의 다른 관광객들로부터 그녀를 격리하는 일을 도와줄 수밖에 없었다.\n이 순간의 모습을 오직 당신 한 사람과 나누는 그녀... 과연 정말로 착각 때문이었을까?",
  str_pet_skin_desc_1601533 = "「정장」, 그것은 일종의 괴물이다. 녀석은 소심하고, 무대를 두려워하고, 스스로에게 회의적인 사람들을 집어삼킨다. 그러나 라인하르트에게는 머리를 숙이고, 오직 그녀의 강인함과 우아함을 강조하려 할 뿐이다.\n절묘한 테일러링은 체형에 딱 맞아 그녀의 잘 단련된 몸의 모든 부분에 감탄하게 만든다. 깔끔한 스타일은 결코 유행에 뒤처지지 않으며, 그녀의 몸에서 확고한 의지가 느껴지게 만든다. 이는 그녀가 시대의 흐름을 선도하려 하는 사람이기 때문이다.\n오늘 밤, 정장은 그녀의 전투복이고, 와인잔은 그녀의 창이다. 단단히 무장하고 연회로 전진하는 그녀는 일루미나의 대원수이자 미래를 주시하는 외교가다.",
  str_pet_skin_desc_1500903 = "뜨거운 태양과 바다, 그리고 뜨거운 무대!\n달콤하고 유쾌한 새로운 모습으로, 여름 축제를 위해 해변에 온 바바라는 가장 열정적인 퍼포먼스를 준비했고, 새로운 무대에서 새로운 팬들을 확보할 것이다.",
  str_pet_skin_desc_1400173 = "시원한 해변, 라비는 멋진 웨이트리스 의상을 입고 가장 생기 넘치는 대표 포즈를 취했고, 그녀는 레디젤의 미식으로 손님들에게 미소를 선사하고 싶었다.\n그러나 「핵불지옥버거」는 라비의 열정 못지않게 매웠다. 누구보다 뜨거운 열정으로 레디젤의 미식을 홍보하려던 계획은 결국 지옥의 매운맛 챌린지로 변해버리고 마는데... 과연 이 매운맛 챌린지에 성공할 수 있는 사람이 있을까.",
  str_pet_skin_desc_1601863 = "봄이 되면 피크닉을 가지 않을 수 없다. 이곳에는 빛과 바람, 맛있는 간식, 그리고 당신이 있다.\n과연 그녀의 진심이 마음속 상대에게 성공적으로 전해질 수 있을까. 그 결과가 어떻든, 모처럼 찾아온 봄날을 헛되이 하지 않으려면 함께하는 이 순간을 소중히 여기는 게 좋을 것 같다.",
  str_pet_skin_desc_1501004 = "검은 상자 안에는 여름의 불꽃놀이도 닿을 수 없는 밤하늘 무덤이 있다. 당신의 침입은 이곳의 괴이한 아름다움을, 그리고 이곳의 감시자를 놀라게 만들었다.\n마력으로 충만한 늪 속에서 그녀의 검은 수영복은 유독 매력적으로 보인다. 하지만 그녀의 곁에서 떨어지지 않도록 조심해야 한다. 그녀는 당신이 오기를 기대했지만, 당신이 이곳의 부장품이 되는 것을 원하지는 않기 때문이다...",
  str_pet_skin_desc_1500213 = "파도는 무정하고, 떨어지는 꽃에는 뜻이 담겨 있다.\n장미로 둘러싸인 외로운 암초 위, 한 퇴폐적이면서도 처량하게 아름다운 모습이 보인다. 그는 이 아름다운 바다를 창조했고, 바닷물에 흠뻑 젖은 그는 곧 이 아름다운 풍경의 일부다.\n완벽한 예술에는 아직 퍼즐의 마지막 한 조각이 부족하다. 그리고 그와 함께 이 걸작을 완성할 사람은 바로 당신이다.",
  str_pet_skin_desc_1602333 = "햇살 아래, 모래사장은 반짝거리고, 푸른 바다는 눈부셨지만, 이보다 더 눈부신 것은 소녀의 미소였다. 여름의 모험은 이제 곧 끝을 맞이하겠지만, 그 소중한 추억과 기억 속 「그들」은 언제나 그녀의 마음속에서 빛날 것이다.",
  str_pet_skin_desc_1501903 = "설령 화려한 정원에 새겨진 보석이라도, 햇살의 비춤과 잔잔한 파도의 연마를 거쳐야만 가장 아름다운 모습을 보여줄 수 있는 법이다. 그러나 어떤 이는 그저 그 자리에 앉아 있는 것만으로도 눈부신 빛을 발할 수 있다.\n생계를 위해 분주히 뛰어다니는 당신은 여유로운 휴가를 보내고 있는 마티외와 우연히 만나게 되었다. 과연 두 사람은 어떤 도전에 함께 직면하게 될까.",
  str_pet_skin_desc_1602273 = "바닷바람은 은은한 멜로디를 연주하고, 물보라는 사냥매의 날개를 씻는다. 소녀는 보드를 날개로 삼아 조류를 타고 날아오르고, 탄창의 탄환을 장전한다. 여유로운 휴일, 그러나 위협이 없다고는 아무도 말할 수 없다. 그녀의 소중한 미소가 곧 살상력이기 때문이다. 조심해야 한다. 그녀의 물총에는 자비가 없다.",
  str_pet_skin_desc_1601733 = "보름달의 밤, 차가운 달빛은 안개를 가르고, 흐느끼는 울음소리 가운데 희미한 불빛이 흔들린다. 여흥을 즐기고 돌아온 그는 마치 고성 속 외로운 장미와도 같다. 핏자국으로 얼룩지고 찢어진 셔츠를 아직 갈아입지 않은 채, 깔끔하고 우아한 예복이 그 위를 덮는다. 창밖 너머의 달빛을 살며시 곁눈질하며 그는 말했다.\n「음식에 대한 제 인내심엔 한계가 있습니다만.」",
  str_pet_skin_desc_1602183 = "푹신한 소파 위, 화려한 드레스의 하늘거리는 천이 샤엘의 아름다운 자태를 드러낸다. 레드 와인의 향기가 방안의 황금빛과 호응하고, 술에 취한 뱀은 나태한 모습으로 술의 욕조에 잠겨 있다. 아름다우면서도 위험한 그녀는 당신의 시선을 느꼈는지, 싱긋이 웃으며 당신을 초대한다.",
  str_pet_skin_desc_1500973 = "「육체의 치유보다 영혼의 구원이 더 중요하다.」\n추운 밤, 프로즌 메스의 칼날이 번쩍이자, 무거운 물건이 땅에 떨어지는 소리와 함께 암살자의 모습도 밤 속으로 숨어버렸다. 그는 훌륭한 의사이고, 고통의 근원을 근절해야만 고통받는 사람을 진정으로 치료할 수 있다는 것을 매우 잘 알고 있다.",
  str_pet_skin_desc_1400953 = "도시의 네온 불빛은 황야의 레인저를 가둘 수 없다. 이 신비한 레인저의 진짜 얼굴을 본 사람은 아무도 없지만, 그녀는 어디를 가든지 늘 군중의 중심이 되곤 한다. 그것은 그녀의 타이트한 복장 때문만이 아니라, 바람처럼 자유분방한 매력 때문이기도 하다.",
  str_pet_skin_name_1602063 = "파란 하늘의 휴가",
  str_pet_skin_desc_1602063 = "푹 누워 있는 것보다 더 편한 게 뭐가 있을까?\n임무도, 전투도 없고, 굳이 의미를 찾지 않아도 돼.\n지금 이 순간의 의미는 내려놓고 즐기는 거니까.\n봐, 저기 밖에서 파닥거리는 비둘기조차 동의하고 있잖아?",
  str_pet_skin_name_1701103 = "적막의 성녀",
  str_pet_skin_desc_1701103 = "혹한의 땅, 북방에 사는 사람들은 폭풍과 눈보라를 견디면서도 앞으로 나아가고 있다. 그들은 자신들의 신념이 성녀의 인도를 통해 얻은 것이라고 했다.\n그러나 그녀는 그들이 폭풍과 천둥, 얼어붙는 추위, 그리고 혐오스러운 괴물들을 정복했다고 말했다. 이 위대한 성취는 남이 준 선물이 아니라, 그들 자신이 만들어낸 기적이다.\n「난 이미 내 사명을 완수했고, 진정한 지도자가 저들 가운데에서 탄생할 거야.」\n그녀의 이야기가 끝나고, 마음속 모든 잡음이 고요해졌을 때, 그녀는 진정한 미소로 빛난다."
}
return config
